root=Path(__file__).resolve().parents[1];out=root/'output/cut-optimizer-verification';read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'));sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
